import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int result = computeResult(n);
        System.out.print(result);
        sc.close();
    }

    private static int computeResult(int n) {
        int total = 2 * n;
        int[][][] dp = new int[total + 1][total + 1][2];
        dp[0][0][0] = 0;
        dp[0][0][1] = 0;
        for (int i = 1; i <= total; i++) {
            for (int j = 0; j <= i; j++) {
                for (int k = 0; k <= 1; k++) {
                    dp[i][j][k] = 0;
                    if (k == 1) {
                        if (i - j >= 2) {
                            dp[i][j][k] = MathUtility.add(dp[i][j][k], dp[i - 1][j + 1][0], 1000000007);
                        }
                        if (j > 0) {
                            dp[i][j][k] = MathUtility.add(dp[i][j][k], dp[i - 1][j - 1][0], 1000000007);
                        }
                    } else {
                        dp[i][j][k] = Math.max(getValue(dp, i, j, false, false),
                                Math.max(getValue(dp, i, j, false, true),
                                        getValue(dp, i, j, true, false)));
                    }
                }
            }
        }
        return dp[total][0][0];
    }

    private static int getValue(int[][][] dp, int i, int j, boolean start, boolean end) {
        int res = 0;
        if (i - j >= 2) {
            if (start) {
                res = MathUtility.add(res, dp[i - 1][j + 1][1], 1000000007);
                res = MathUtility.add(res, 1, 1000000007);
            } else {
                res = MathUtility.add(res, dp[i - 1][j + 1][0], 1000000007);
            }
        }
        if (j > 0) {
            if (end) {
                res = MathUtility.add(res, dp[i - 1][j - 1][1], 1000000007);
                res = MathUtility.add(res, 1, 1000000007);
            } else {
                res = MathUtility.add(res, dp[i - 1][j - 1][0], 1000000007);
            }
        }
        return res;
    }

    static class MathUtility {
        public static int add(int a, int b, int MOD) {
            int res = a + b;
            if (res >= MOD) {
                res -= MOD;
            }
            return res;
        }
    }
}
