MOD = 1000000007

def add(a, b, mod=MOD):
    res = a + b
    if res >= mod:
        res -= mod
    return res

def get_value(dp, i, j, start, end):
    res = 0
    if i - j >= 2:
        if start:
            res = add(res, dp[i - 1][j + 1][1], MOD)
            res = add(res, 1, MOD)
        else:
            res = add(res, dp[i - 1][j + 1][0], MOD)
    if j > 0:
        if end:
            res = add(res, dp[i - 1][j - 1][1], MOD)
            res = add(res, 1, MOD)
        else:
            res = add(res, dp[i - 1][j - 1][0], MOD)
